mapper.sql:
SELECT cand_id,cand_no,cand_nm,cand_se_cd,vndr_ptnr_id,job_cd,grd_cd,hope_untprc_amt,
  asgn_psbl_dt AS avail_dt,cntct_stts_cd,last_cntct_dt,cand_src_cd AS source,
  tel_no,memo_desc AS rmrk_desc,dev_id,use_yn,created_at FROM hr.cand WHERE cand_id=#{id}

mapper.update:
UPDATE hr.cand c SET cntct_stts_cd=CASE WHEN c.dev_id IS NOT NULL THEN 'SIGNED' ELSE h.cntct_stts_cd END,
  last_cntct_dt=h.cntct_dt,updated_by=#{actor}
FROM (SELECT cntct_dt,cntct_stts_cd FROM hr.cand_cntct_hist WHERE cand_id=#{id}
  ORDER BY cntct_dt DESC,created_at DESC,cntct_hist_id DESC LIMIT 1) h
WHERE c.cand_id=#{id}
  AND (c.last_cntct_dt IS DISTINCT FROM h.cntct_dt
    OR c.cntct_stts_cd IS DISTINCT FROM CASE WHEN c.dev_id IS NOT NULL THEN 'SIGNED' ELSE h.cntct_stts_cd END)

mapper.select:
SELECT count(DISTINCT c.cand_id) FROM hr.cand c
WHERE c.use_yn='Y' AND c.cntct_stts_cd IN ('NONE','DONE','INTV') AND c.job_cd=#{job}
AND c.grd_cd=#{grade}
AND c.asgn_psbl_dt <= #{monthEnd}
